import{_ as o,r as n,o as p,c as l,e as s,a as c,s as r}from"./chunks/framework.CXcwiNg-.js";const v=JSON.parse('{"title":"AJAX - October CMS - 4.x","titleTemplate":false,"description":"Discover how to use AJAX in the backend panel.","frontmatter":{"subtitle":"Discover how to use AJAX in the backend panel."},"headers":[{"level":2,"title":"Backend AJAX Handlers","slug":"backend-ajax-handlers","link":"#backend-ajax-handlers","children":[{"level":3,"title":"Triggering AJAX Requests","slug":"triggering-ajax-requests","link":"#triggering-ajax-requests","children":[]}]},{"level":2,"title":"Behavior AJAX Handlers","slug":"behavior-ajax-handlers","link":"#behavior-ajax-handlers","children":[]},{"level":2,"title":"Widget AJAX Handlers","slug":"widget-ajax-handlers","link":"#widget-ajax-handlers","children":[{"level":4,"title":"See Also","slug":"see-also","link":"#see-also","children":[]}]}],"relativePath":"4.x/extend/system/ajax.md","filePath":"4.x/extend/system/ajax.md"}'),i={name:"4.x/extend/system/ajax.md"};function u(d,a,h,k,g,m){const t=n("pre-heading"),e=n("post-heading");return p(),l("div",null,[s(t),a[0]||(a[0]=c("h1",null,"AJAX",-1)),s(e),a[1]||(a[1]=r(`<p>The backend panel uses the same <a href="./../../cms/ajax/introduction.html">AJAX library as the CMS</a> pages. The library is included and loaded automatically on the backend pages.</p><h2 id="backend-ajax-handlers"><a href="#backend-ajax-handlers" class="header-anchor">#</a> Backend AJAX Handlers</h2><p>The backend AJAX handlers can be defined in the controller class or widgets. In the controller class the AJAX handlers are defined as public methods with the name starting with &quot;on&quot; string: <strong>onCreateTemplate</strong>, <strong>onGetTemplateList</strong>, etc.</p><p>Backend AJAX handlers can return an array of data, throw an exception or redirect to another page. You can use <code>$this-&gt;vars</code> to set variables and the controller&#39;s <code>makePartial</code> method to render a partial and return its contents as a part of the response data.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">public</span> <span class="token keyword">function</span> <span class="token function-definition function">onOpenTemplate</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token keyword">if</span> <span class="token punctuation">(</span><span class="token function">post</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;someVar&#39;</span><span class="token punctuation">)</span> <span class="token operator">!==</span> <span class="token string single-quoted-string">&#39;someValue&#39;</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
        <span class="token keyword">throw</span> <span class="token keyword">new</span> <span class="token class-name">ApplicationException</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;Invalid value&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>

    <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token property">vars</span><span class="token punctuation">[</span><span class="token string single-quoted-string">&#39;foo&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> <span class="token string single-quoted-string">&#39;bar&#39;</span><span class="token punctuation">;</span>

    <span class="token keyword">return</span> <span class="token punctuation">[</span>
        <span class="token string single-quoted-string">&#39;partialContents&#39;</span> <span class="token operator">=&gt;</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">makePartial</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;some-partial&#39;</span><span class="token punctuation">)</span>
    <span class="token punctuation">]</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h3 id="triggering-ajax-requests"><a href="#triggering-ajax-requests" class="header-anchor">#</a> Triggering AJAX Requests</h3><p>The AJAX request can be triggered with the data attributes API or the JavaScript API. Please see the <a href="./../../ajax/introduction.html">frontend AJAX library</a> for details. The following example shows how to trigger a request with a backend button.</p><div class="language-html extra-class"><pre class="language-html"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>button</span>
    <span class="token attr-name">type</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>button<span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>onDoSomething<span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>btn btn-default<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    Do Something
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>button</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><h2 id="behavior-ajax-handlers"><a href="#behavior-ajax-handlers" class="header-anchor">#</a> Behavior AJAX Handlers</h2><p>Since behaviors will combine their methods to the parent controller, all AJAX handlers that are defined in a behavior are available to the controller. In some cases you may want to override an AJAX handler in the controller, you may do this by calling the <code>asExtension</code> method.</p><p>The controller AJAX handler takes priority, then requests the <code>Backend\\Behaviors\\FormController</code> behavior and calls its handler.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token keyword">function</span> <span class="token function-definition function">onDoSomething</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    <span class="token comment">// Custom logic here</span>
    <span class="token comment">// ...</span>

    <span class="token comment">// Call the extension handler</span>
    <span class="token keyword">return</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">asExtension</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;FormController&#39;</span><span class="token punctuation">)</span><span class="token operator">-&gt;</span><span class="token function">doSomething</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre></div><h2 id="widget-ajax-handlers"><a href="#widget-ajax-handlers" class="header-anchor">#</a> Widget AJAX Handlers</h2><p>Widgets implement the same AJAX approach as the backend controllers. The AJAX handlers are public methods of the widget class with names starting with the <strong>on</strong> prefix. The only difference between the widget AJAX handlers and backend controller&#39;s AJAX handlers is that you should use the widget&#39;s <code>getEventHandler</code> method to return the widget&#39;s handler name when you refer to it in the widget partials.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>a</span>
    <span class="token attr-name">href</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>javascript:;<span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">data-request</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span><span class="token php language-php"><span class="token delimiter important">&lt;?=</span> <span class="token variable">$this</span><span class="token operator">-&gt;</span><span class="token function">getEventHandler</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;onPaginate&#39;</span><span class="token punctuation">)</span> <span class="token delimiter important">?&gt;</span></span><span class="token punctuation">&quot;</span></span>
    <span class="token attr-name">title</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>Next page<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>Next<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>a</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>When called from a widget class or partial the AJAX handler will target itself. For example, if the widget uses the alias of <strong>mywidget</strong> the handler will be targeted with <code>mywidget::onName</code>. The above would output the following attribute value:</p><div class="language-html extra-class"><pre class="language-html"><code>data-request=&quot;mywidget::onPaginate&quot;
</code></pre></div><h4 id="see-also"><a href="#see-also" class="header-anchor">#</a> See Also</h4><div class="custom-block also"><ul><li><a href="./../../ajax/introduction.html">AJAX Framework Guide</a></li></ul></div>`,19))])}const f=o(i,[["render",u]]);export{v as __pageData,f as default};
